/** Actual statement-set child views through the existing v2 consumer;no UI/server. */
import {readFileSync,statSync} from 'node:fs';import assert from 'node:assert/strict';
import {parseOfflineJson} from '../web/src/offlineJson.ts';
import {verifyStatementProfile} from '../web/src/xbrlAccuracy.ts';
import {verifyXbrlDigest} from '../web/src/xbrlStatements.ts';
import {acceptanceNanoseconds} from '../web/src/acceptanceContract.ts';
const path=process.argv[2];assert.ok(path&&statSync(path).size<=2*1024*1024);
// This bounded file is test-harness metadata generated by the companion Python
// program. Each actual v2 consumer packet crosses its real strict import boundary.
const fixture=JSON.parse(readFileSync(path,'utf8'));assert.equal(fixture.schema,'gig.statement_set.developer_contract_fixture.v1');
const kinds=['balance_sheet','income_statement','cash_flow_statement'];let assertions=0,verifiedChildren=0,rejections=0;
const eq=(a,b)=>{assert.deepEqual(a,b);assertions++;};
async function checkSet(p,children,sources){
 await verifyXbrlDigest(p);assertions++;
 eq(p.schema,'gig.backend.company_statement_set.v1');eq(p.read_only,true);eq(p.provider_requested,false);eq(p.complete_statements,false);eq(p.complete_history,false);
 eq(p.cutoff_ns,acceptanceNanoseconds(p.as_of).toString());
 if(p.source_filing===null){eq(p.status,'UNAVAILABLE');eq(p.parsed_sha256,null);eq(Object.keys(children),[]);return;}
 const expected=sources[p.source_filing.accession];assert.ok(expected);assertions++;
 eq(p.source_filing,expected.source);eq(p.parsed_sha256,expected.original_parsed_sha256);eq(p.dts_sha256,expected.dts_sha256);
 await verifyXbrlDigest({issuer_cik:p.source_filing.issuer_cik,accession:p.source_filing.accession,dts_sha256:p.dts_sha256,roles:expected.roles,sha256:p.role_bindings_sha256});assertions++;
 await verifyXbrlDigest(p.lineage);assertions++;
 eq(p.lineage.selected_accession,p.source_filing.accession);eq(p.lineage.collection_sha256,p.collection_sha256);eq(p.lineage.cutoff_ns,p.cutoff_ns);eq(p.lineage.status,'SUPPLIED_CHAIN_RESOLVED');
 eq(p.lineage.sources[0].parsed_sha256,p.parsed_sha256);eq(p.lineage.complete_history,false);eq(p.lineage.links.length,p.lineage.sources.length-1);
 for(let i=0;i<p.lineage.links.length;i++){const child=p.lineage.sources[i].source,parent=p.lineage.sources[i+1].source,link=p.lineage.links[i];eq(child.amends_accession,parent.accession);eq(link,{from_accession:child.accession,to_accession:parent.accession,basis:'EXPLICIT_SOURCE_MANIFEST'});}
 for(const ancestor of p.lineage.sources){const original=sources[ancestor.source.accession];assert.ok(original);assertions++;eq(ancestor.source,original.source);eq(ancestor.parsed_sha256,original.original_parsed_sha256);assert.ok(acceptanceNanoseconds(ancestor.source.accepted_at)<=acceptanceNanoseconds(p.as_of));assertions++;}
 eq(Object.keys(p.statements).sort(),[...kinds].sort());eq(Object.keys(children).sort(),[...kinds].sort());
 for(const kind of kinds){
  const descriptor=p.statements[kind],wrapper=children[kind];eq(descriptor.role,expected.roles[kind]);
  if(descriptor.view===null){eq(wrapper,null);eq(descriptor.status,'UNAVAILABLE');eq(descriptor.reason,'ROLE_NOT_DESIGNATED');continue;}
  eq(wrapper.statement_view,descriptor.view);eq(wrapper.instrument,p.instrument);eq(wrapper.read_only,true);eq(wrapper.provider_requested,false);
  const verified=await verifyStatementProfile(parseOfflineJson(JSON.stringify(wrapper)),'AAPL','0000320193','accuracy-extension-v2');verifiedChildren++;assertions++;
  const s=verified.statement_view;eq(s.source_filing,p.source_filing);eq(s.collection_sha256,p.collection_sha256);eq(s.selected_instance_sha256,expected.revalidated_parsed_sha256);eq(s.role,descriptor.role);eq(s.as_of,p.as_of);eq(s.cutoff_ns,p.cutoff_ns);
  if(s.status==='AVAILABLE'){eq(s.source_documents,expected.documents);eq(s.relationship_sha256,expected.relationships_sha256);}
  eq(s.source_contexts,s.status==='AVAILABLE'?expected.contexts:{});eq(s.source_units,s.status==='AVAILABLE'?expected.units:{});
  for(const period of s.periods)for(const row of period.rows){eq(row.statement_mapping.accounting_metric,null);for(const fact of row.facts){assert.ok(expected.source_fact_ids.includes(fact.source_fact_id));assertions++;}for(const fact of row.numeric_facts)eq(fact.filing_accession,p.source_filing.accession);}
 }
}
for(const row of fixture.sets){await checkSet(row.packet,row.children,row.sources);
 if(row.name==='three_roles'){eq(row.packet.status,'AVAILABLE');for(const [kind,values]of kinds.map((k,i)=>[k,[['1000','600','400'],['100','150','50'],['30','50','20']][i]]))eq(row.packet.statements[kind].view.periods[0].rows.map(r=>r.value),values);}
 if(row.name==='numeric_proof_rebound'){assert.notEqual(row.packet.parsed_sha256,row.packet.statements.balance_sheet.view.selected_instance_sha256);assertions++;}
 if(row.name==='conflicting_income'){const r=row.packet.statements.income_statement.view.periods[0].rows[0];eq(r.status,'CONFLICT');eq(r.value,null);eq(r.facts.length,2);}
 if(row.name==='explicit_partial'){eq(row.packet.status,'PARTIAL');eq(row.packet.statements.income_statement.reason,'ROLE_NOT_IN_LATEST_FILING');eq(row.packet.statements.cash_flow_statement.reason,'ROLE_NOT_DESIGNATED');}
 if(row.name==='comparative_missing'){const r=row.packet.statements.income_statement.view.periods[1];eq(r.start,'2022-01-01');eq(r.rows.map(x=>x.status),['MISSING','REPORTED_EXTENSION','MISSING']);eq(r.rows[1].value,'125');}
}
const history=fixture.history;await verifyXbrlDigest(history.packet);assertions++;eq(history.packet.schema,'gig.backend.company_statement_history.v1');eq(history.packet.complete_history,false);eq(history.packet.entries.map(e=>e.transition),['UNAVAILABLE','FIRST_AVAILABLE','SOURCE_CHANGED','UNCHANGED_SOURCE']);
let previous=null,prior=null;
for(let i=0;i<history.packet.entries.length;i++){const e=history.packet.entries[i],packet=e.packet;await checkSet(packet,history.children[i],history.sources);eq(packet.collection_sha256,history.packet.collection_sha256);eq(e.previous_accession,previous);const instant=acceptanceNanoseconds(packet.as_of);if(prior!==null){assert.ok(instant>prior);assertions++;}prior=instant;if(packet.status!=='UNAVAILABLE')previous=packet.source_filing.accession;}
eq(history.packet.entries[1].packet.statements.income_statement.view.periods[0].rows[0].value,'100');eq(history.packet.entries[2].packet.statements.income_statement.view.periods[0].rows[0].value,'99');eq(history.packet.entries[2].packet.lineage.sources.length,2);
const acceptedChildren=verifiedChildren;const base=fixture.sets[0];
for(const mutation of ['child_source','outer_source','role_identity','original_identity','context_identity','ancestor_identity','view_source_swap']){
 const p=structuredClone(base.packet),children=structuredClone(base.children);
 if(mutation==='child_source'){children.balance_sheet.statement_view.source_filing.accession='0000000123-24-000099';p.statements.balance_sheet.view=structuredClone(children.balance_sheet.statement_view);}
 if(mutation==='outer_source')p.source_filing.source_sha256='0'.repeat(64);
 if(mutation==='role_identity')p.role_bindings_sha256='0'.repeat(64);
 if(mutation==='original_identity')p.parsed_sha256='0'.repeat(64);
 if(mutation==='context_identity'){children.income_statement.statement_view.source_contexts.FD.semantic_sha256='0'.repeat(64);p.statements.income_statement.view=structuredClone(children.income_statement.statement_view);}
 if(mutation==='ancestor_identity')p.lineage.sources[0].parsed_sha256='0'.repeat(64);
 if(mutation==='view_source_swap'){children.income_statement=structuredClone(history.children[2].income_statement);p.statements.income_statement.view=structuredClone(children.income_statement.statement_view);}
 // Re-sign the forged containers: source/role/lineage checks must not rely only
 // on stale digests. Existing v2 admission remains part of each child path.
 const {createHash}=await import('node:crypto');const sign=o=>{const canon=v=>v===null?'null':typeof v==='string'?JSON.stringify(v):typeof v==='number'||typeof v==='boolean'?JSON.stringify(v):Array.isArray(v)?'['+v.map(canon).join(',')+']':'{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canon(v[k])).join(',')+'}';delete o.sha256;o.sha256=createHash('sha256').update(canon(o)).digest('hex');};
 for(const wrapper of Object.values(children)){if(wrapper){sign(wrapper.statement_view);sign(wrapper);}}
 sign(p.lineage);sign(p);
 await assert.rejects(checkSet(p,children,base.sources));rejections++;
}
console.log(JSON.stringify({schema:'gig.statement_set.offline_consumer_contract.v1',fixture_bytes:statSync(path).size,sets:fixture.sets.length,history_entries:history.packet.entries.length,verified_children:acceptedChildren,assertions,adversarial_rejections:rejections,application_started:false,provider_requested:false}));
